"""仅展示真实保存的逐帧证据，不重画论文图，不授予自报成功信用。"""
import json,os
from pathlib import Path
from conceptgraph.completion.stage9 import dump,digest
R=Path(__file__).resolve().parents[1];O=R/'carla_official/inspection_001'
def main():
 O.mkdir(exist_ok=False);cases=[];sources={}
 for e in sorted((R/'carla_official/ablation_batch_003').glob('*/*')):
  p=e/'perception.jsonl';x=e/'execution.jsonl'
  if not p.exists() or not x.exists():continue
  observations=list(map(json.loads,p.open()));execution={z['frame']:z for z in map(json.loads,x.open())};audit=e/'independent_audit_003/frames.jsonl';independent={z['tick']:z for z in map(json.loads,audit.open())} if audit.exists() else {};frames=[]
  for z in observations:
   state=execution.get(z['sensor_frame'])
   if state is None:continue
   folder=e/'frames'/f"{z['frame_idx']:06d}";frames.append(dict(idx=z['frame_idx'],time=z['sim_time_s'],folder=os.path.relpath(folder,O),nodes=[dict(id=n['node_id'],category=n['category'],center=n['center'],motion=n['motion'],observations=n['metadata']['num_detections'],depth=n['metadata'].get('depth_evidence',[])) for n in z['nodes']],relations=z['relations'],candidates=z['candidates'],lock=z['lock'],selected=z['selected_node_id'],path_points=len(z['path_world']),path_purpose=z['path_purpose'],vehicle_state=state['state'],applied_control=state['applied_control'],independent_audit=independent.get(state['tick']),reported_evaluation=state['evaluation']))
  sources[str(p)]=digest(p);sources[str(x)]=digest(x);s=e/'summary.json';cases.append(dict(name='/'.join(e.parts[-2:]),complete=s.exists(),summary=json.loads(s.read_text()) if s.exists() else json.loads((e/'failure.json').read_text()),root=os.path.relpath(e,O),frames=frames))
 html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>官方CARLA逐帧实验核查</title><style>body{font:16px system-ui;max-width:1250px;margin:24px auto;padding:12px;background:#f5f6f8;color:#18212d}select,input,button{font:inherit;padding:7px}input{width:55%}.images{display:grid;grid-template-columns:1fr 1fr;gap:12px}img{width:100%;background:#ddd}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;border:1px solid #ddd;padding:12px;max-height:400px;overflow:auto}a{margin-right:15px}h2{font-size:20px}.note{background:#fff3d5;padding:12px}button{cursor:pointer}</style><h1>官方CARLA逐帧实验核查</h1><p class="note">14回合完成；第15回合因10 GiB存储守卫停止，原始前缀保留。本页展示原始传感器图片和实际记录。清晰类别规则链未激活复杂Qwen；路线、候选、首位提议、锁定、独立几何到达和严格安全到达不能混算。</p><select id="case"></select><p><button id="previous">上一帧</button> <input id="frame" type="range" min="0" value="0"> <button id="next">下一帧</button> <span id="position"></span></p><div class="images"><div>真实RGB<img id="rgb" alt="实际RGB输入"></div><div>真实检测/分割叠图<img id="detection" alt="实际前端检测和SAM叠图"></div></div><p id="links"></p><h2>本回合结果与范围</h2><pre id="summary"></pre><h2>该帧候选、锁定和执行</h2><pre id="decision"></pre><h2>实际对象与关系</h2><pre id="nodes"></pre><script>
const DATA=__DATA__;const selector=document.getElementById('case'),slider=document.getElementById('frame');DATA.forEach((x,i)=>{const o=document.createElement('option');o.value=i;o.textContent=x.name+(x.complete?'（完成）':'（中断前缀）');selector.append(o)});
function link(parent,label,path){const a=document.createElement('a');a.textContent=label;a.href=path;parent.append(a)}
function render(){const c=DATA[Number(selector.value)],i=Math.min(Number(slider.value),c.frames.length-1),v=c.frames[i];document.getElementById('position').textContent=`感知帧 ${i+1}/${c.frames.length}，仿真时间 ${v.time.toFixed(1)} 秒`;document.getElementById('rgb').src=v.folder+'/rgb.png';document.getElementById('detection').src=v.folder+'/detections.jpg';const links=document.getElementById('links');links.textContent='';[['LiDAR原始点',v.folder+'/lidar.bin'],['投影深度（16位毫米）',v.folder+'/lidar_depth_mm.png'],['官方原始24位深度',v.folder+'/official_depth_raw_bgr.png'],['可逆掩膜/CLIP',v.folder+'/detections_compact.pkl.gz'],['原始感知JSONL',c.root+'/perception.jsonl'],['原始执行JSONL',c.root+'/execution.jsonl']].forEach(x=>link(links,...x));document.getElementById('summary').textContent=JSON.stringify(c.summary,null,2);document.getElementById('decision').textContent=JSON.stringify({time_s:v.time,candidates:v.candidates,first_proposal:v.candidates[0]||null,selected:v.selected,lock:v.lock,path_points:v.path_points,path_purpose:v.path_purpose,vehicle_state:v.vehicle_state,applied_control:v.applied_control,independent_audit:v.independent_audit,reported_evaluation:v.reported_evaluation},null,2);document.getElementById('nodes').textContent=JSON.stringify({nodes:v.nodes,relations:v.relations},null,2)}
function changeCase(){slider.max=DATA[Number(selector.value)].frames.length-1;slider.value=0;render()}selector.onchange=changeCase;slider.oninput=render;document.getElementById('previous').onclick=()=>{slider.value=Math.max(0,Number(slider.value)-1);render()};document.getElementById('next').onclick=()=>{slider.value=Math.min(Number(slider.max),Number(slider.value)+1);render()};changeCase();
</script></html>'''.replace('__DATA__',json.dumps(cases,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
 (O/'index.html').write_text(html);dump(O/'receipt.json',dict(episodes=len(cases),complete_episodes=sum(c['complete'] for c in cases),perception_frames=sum(len(c['frames']) for c in cases),raw_images_duplicated=False,source_sha256=sources,generator_sha256=digest(__file__),browser_execution_verified=False,static_inputs_and_local_references=True,formal_scientific_plot=False,goal_complete=False));print(json.dumps(dict(cases=len(cases),frames=sum(len(c['frames']) for c in cases),html_bytes=len(html.encode())),ensure_ascii=False))
if __name__=='__main__':main()
